{
  "$schema": "https://json.schemastore.org/package.json",
  "name": "@forget2save/opencode-trajectory",
  "version": "0.1.1",
  "description": "Inspect and export complete OpenCode conversation trajectories, including tools, reasoning, changes, compaction, and child sessions.",
  "type": "module",
  "license": "MIT",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    },
    "./core": {
      "types": "./dist/core.d.ts",
      "import": "./dist/core.js"
    },
    "./tui": {
      "types": "./dist/tui.d.ts",
      "import": "./dist/tui.js"
    }
  },
  "files": [
    "dist",
    "README.md",
    "LICENSE"
  ],
  "keywords": [
    "opencode",
    "opencode-plugin",
    "trajectory",
    "conversation",
    "trace",
    "debugging",
    "tui"
  ],
  "scripts": {
    "build": "tsup",
    "typecheck": "tsc --noEmit",
    "test": "npm run build && bun --conditions=browser test tests",
    "smoke": "node scripts/plugin-smoke.mjs",
    "verify": "npm run typecheck && npm test && npm run smoke",
    "prepack": "npm run verify"
  },
  "engines": {
    "node": ">=22",
    "opencode": ">=1.16.0 <1.19.0"
  },
  "publishConfig": {
    "access": "public"
  },
  "dependencies": {
    "@opencode-ai/plugin": ">=1.16.0 <1.19.0"
  },
  "peerDependencies": {
    "@opentui/core": "0.4.5",
    "@opentui/solid": "0.4.5",
    "solid-js": "1.9.12"
  },
  "devDependencies": {
    "@opencode-ai/plugin": "1.16.0",
    "@opentui/core": "0.4.5",
    "@opentui/solid": "0.4.5",
    "@types/node": "^24.3.0",
    "esbuild-plugin-solid": "^0.6.0",
    "solid-js": "1.9.12",
    "tsup": "^8.5.0",
    "typescript": "^5.9.2"
  }
}
